@props([
    'type' => 'single',
    'variant' => 'default',
    'size' => null,
    'orientation' => 'horizontal',
    'spacing' => 0,
    'defaultValue' => null,
    'disabled' => false,
])

@php
    $type = $type === 'multiple' ? 'multiple' : 'single';
    $variant = in_array($variant, ['default', 'outline'], true) ? $variant : 'default';
    $size = match ($size) {
        'sm', 'lg' => $size,
        'xs' => 'sm',
        default => 'default',
    };
    $orientation = $orientation === 'vertical' ? 'vertical' : 'horizontal';
    $spacing = is_numeric($spacing) ? max(0, (int) $spacing) : 0;
    $isDisabled = (bool) $disabled;

    $initialValue = match (true) {
        is_array($defaultValue) => implode(',', array_map(static fn ($item): string => (string) $item, $defaultValue)),
        filled($defaultValue) => (string) $defaultValue,
        default => '',
    };

    $role = $type === 'single' ? 'radiogroup' : 'group';
@endphp

<div {{
    $attributes->class([
        'toggle-group',
        'group/toggle-group flex w-fit items-center rounded-md',
        $orientation === 'vertical' ? 'flex-col' : 'flex-row',
        $spacing > 0 ? 'gap-[length:var(--toggle-gap)]' : null,
        $spacing === 0 && $variant === 'outline' ? 'shadow-sm' : null,
    ])->merge([
        'role' => $role,
        'data-toggle-group' => true,
        'data-type' => $type,
        'data-variant' => $variant,
        'data-size' => $size,
        'data-orientation' => $orientation,
        'data-spacing' => (string) $spacing,
        'data-value' => $initialValue !== '' ? $initialValue : null,
        'data-disabled' => $isDisabled ? 'true' : null,
        'aria-disabled' => $isDisabled ? 'true' : null,
        'aria-orientation' => $orientation,
        'style' => $spacing > 0 ? '--toggle-gap: '.$spacing * 0.25.'rem' : null,
    ])
}}>
    {{ $slot }}
</div>

@props([
    'value',
    'disabled' => false,
])

@aware([
    'type' => 'single',
    'variant' => 'default',
    'size' => null,
    'orientation' => 'horizontal',
    'spacing' => 0,
    'defaultValue' => null,
    'disabled' => false,
])

@php
    $itemValue = (string) $value;
    $groupType = $type === 'multiple' ? 'multiple' : 'single';
    $groupVariant = in_array($variant, ['default', 'outline'], true) ? $variant : 'default';
    $groupSize = match ($size) {
        'sm', 'lg' => $size,
        'xs' => 'sm',
        default => 'default',
    };
    $groupSpacing = is_numeric($spacing) ? max(0, (int) $spacing) : 0;
    $groupOrientation = $orientation === 'vertical' ? 'vertical' : 'horizontal';
    $isDisabled = (bool) $disabled;

    $selectedValues = match (true) {
        is_array($defaultValue) => array_map(static fn ($item): string => (string) $item, $defaultValue),
        filled($defaultValue) => array_values(array_filter(array_map(
            static fn (string $item): string => trim($item),
            explode(',', (string) $defaultValue),
        ), static fn (string $item): bool => $item !== '')),
        default => [],
    };
    $isSelected = in_array($itemValue, $selectedValues, true);

    $sizeClasses = match ($groupSize) {
        'sm' => 'h-8 min-w-8 px-2 text-sm',
        'lg' => 'h-10 min-w-10 px-3 text-base',
        default => 'h-9 min-w-9 px-3 text-sm',
    };

    $variantClasses = match ($groupVariant) {
        'outline' => implode(' ', [
            'border border-zinc-200 bg-transparent shadow-none',
            'hover:bg-zinc-100 hover:text-zinc-900',
            'dark:border-zinc-800 dark:hover:bg-zinc-800 dark:hover:text-zinc-50',
        ]),
        default => implode(' ', [
            'bg-transparent',
            'hover:bg-zinc-100 hover:text-zinc-900',
            'dark:hover:bg-zinc-800 dark:hover:text-zinc-50',
        ]),
    };

    $connectedClasses = $groupSpacing === 0
        ? collect([
            'rounded-none shadow-none',
            $groupOrientation === 'vertical'
                ? 'first:rounded-t-md last:rounded-b-md'
                : 'first:rounded-l-md last:rounded-r-md',
            $groupVariant === 'outline' && $groupOrientation === 'vertical'
                ? 'border-t-0 first:border-t'
                : null,
            $groupVariant === 'outline' && $groupOrientation === 'horizontal'
                ? 'border-l-0 first:border-l'
                : null,
        ])->filter()->implode(' ')
        : 'rounded-md';

    $role = $groupType === 'single' ? 'radio' : 'button';
@endphp

<button
    type="button"
    {{
        $attributes->class([
            'toggle-group__item',
            'inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap font-medium',
            'transition-colors outline-none',
            'focus:z-10 focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-zinc-950/10',
            'dark:focus-visible:ring-zinc-300/20',
            'disabled:pointer-events-none disabled:opacity-50',
            'cursor-pointer',
            '[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*=size-])]:size-4',
            'data-[state=on]:bg-zinc-100 data-[state=on]:text-zinc-900',
            'dark:data-[state=on]:bg-zinc-800 dark:data-[state=on]:text-zinc-50',
            $sizeClasses,
            $variantClasses,
            $connectedClasses,
        ])->merge([
            'role' => $role,
            'data-toggle-group-item' => true,
            'data-value' => $itemValue,
            'data-variant' => $groupVariant,
            'data-size' => $groupSize,
            'data-spacing' => (string) $groupSpacing,
            'data-state' => $isSelected ? 'on' : 'off',
            'aria-checked' => $groupType === 'single' ? ($isSelected ? 'true' : 'false') : null,
            'aria-pressed' => $groupType === 'multiple' ? ($isSelected ? 'true' : 'false') : null,
            'tabindex' => $groupType === 'single' ? ($isSelected ? '0' : '-1') : '0',
            'disabled' => $isDisabled ? true : null,
        ])
    }}
>
    {{ $slot }}
</button>

/**
 * Stencil — accessible toggle group (vanilla JS, no Alpine).
 */

const GROUP_SELECTOR = '[data-toggle-group]';
const ITEM_SELECTOR = '[data-toggle-group-item]';
const initialized = new WeakSet();

/**
 * @param {ParentNode} root
 */
export function initToggleGroups(root = document) {
    root.querySelectorAll(GROUP_SELECTOR).forEach((element) => {
        if (!(element instanceof HTMLElement)) {
            return;
        }

        if (initialized.has(element)) {
            return;
        }

        initialized.add(element);
        bindToggleGroup(element);
    });
}

/**
 * @param {HTMLElement} root
 */
function bindToggleGroup(root) {
    const type = root.dataset.type === 'multiple' ? 'multiple' : 'single';
    const orientation = root.dataset.orientation === 'vertical' ? 'vertical' : 'horizontal';

    /** @returns {HTMLButtonElement[]} */
    const items = () =>
        Array.from(root.querySelectorAll(ITEM_SELECTOR)).filter(
            (node) => node instanceof HTMLButtonElement && !node.disabled,
        );

    /**
     * @param {HTMLButtonElement} item
     * @param {boolean} selected
     */
    const setItemState = (item, selected) => {
        item.dataset.state = selected ? 'on' : 'off';

        if (type === 'single') {
            item.setAttribute('aria-checked', selected ? 'true' : 'false');
            item.tabIndex = selected ? 0 : -1;
            item.removeAttribute('aria-pressed');
        } else {
            item.setAttribute('aria-pressed', selected ? 'true' : 'false');
            item.tabIndex = 0;
            item.removeAttribute('aria-checked');
        }
    };

    /**
     * @returns {string[]}
     */
    const selectedValues = () =>
        items()
            .filter((item) => item.dataset.state === 'on')
            .map((item) => item.dataset.value)
            .filter((value) => typeof value === 'string');

    /**
     * @param {string[]} values
     */
    const sync = (values) => {
        const unique = [...new Set(values)];

        items().forEach((item) => {
            const value = item.dataset.value;
            setItemState(item, typeof value === 'string' && unique.includes(value));
        });

        if (type === 'single' && unique.length === 0) {
            const first = items()[0];

            if (first) {
                first.tabIndex = 0;
            }
        }

        root.dataset.value = unique.join(',');

        root.dispatchEvent(
            new CustomEvent('stencil:toggle-group:change', {
                bubbles: true,
                detail: {
                    type,
                    value: type === 'single' ? (unique[0] ?? null) : unique,
                },
            }),
        );
    };

    const initial = (root.dataset.value || '')
        .split(',')
        .map((value) => value.trim())
        .filter((value) => value !== '');

    if (initial.length > 0) {
        sync(type === 'single' ? [initial[0]] : initial);
    } else {
        sync(selectedValues());
    }

    root.addEventListener('click', (event) => {
        if (root.dataset.disabled === 'true') {
            return;
        }

        const item = event.target instanceof Element ? event.target.closest(ITEM_SELECTOR) : null;

        if (!(item instanceof HTMLButtonElement) || !root.contains(item) || item.disabled) {
            return;
        }

        const value = item.dataset.value;

        if (typeof value !== 'string') {
            return;
        }

        if (type === 'single') {
            const current = selectedValues()[0] ?? null;
            sync(current === value ? [] : [value]);
        } else {
            const current = selectedValues();
            sync(
                current.includes(value)
                    ? current.filter((entry) => entry !== value)
                    : [...current, value],
            );
        }
    });

    root.addEventListener('keydown', (event) => {
        const item = event.target instanceof Element ? event.target.closest(ITEM_SELECTOR) : null;

        if (!(item instanceof HTMLButtonElement) || !root.contains(item)) {
            return;
        }

        const enabled = items();
        const index = enabled.indexOf(item);
        const nextKey = orientation === 'vertical' ? 'ArrowDown' : 'ArrowRight';
        const prevKey = orientation === 'vertical' ? 'ArrowUp' : 'ArrowLeft';

        let nextIndex = index;

        if (event.key === nextKey) {
            nextIndex = index + 1 >= enabled.length ? 0 : index + 1;
        } else if (event.key === prevKey) {
            nextIndex = index - 1 < 0 ? enabled.length - 1 : index - 1;
        } else if (event.key === 'Home') {
            nextIndex = 0;
        } else if (event.key === 'End') {
            nextIndex = enabled.length - 1;
        } else if (event.key === ' ' || event.key === 'Enter') {
            if (type === 'single' && event.key === ' ') {
                event.preventDefault();
                item.click();
            }

            return;
        } else {
            return;
        }

        event.preventDefault();
        const next = enabled[nextIndex];

        if (next instanceof HTMLButtonElement) {
            next.focus();

            if (type === 'single') {
                const value = next.dataset.value;

                if (typeof value === 'string') {
                    sync([value]);
                }
            }
        }
    });
}

document.addEventListener('stencil:mount', (event) => {
    if (!(event instanceof CustomEvent)) {
        return;
    }

    const mountRoot = event.detail?.root;

    if (!(mountRoot instanceof HTMLElement)) {
        return;
    }

    initToggleGroups(mountRoot);
});

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => initToggleGroups());
    } else {
        initToggleGroups();
    }
}
